'use strict';

/**
 * Provider-independent workspace monitoring matrix.
 *
 * The matrix describes where code can be observed once it exists in a VS Code
 * workspace. It does not claim that a line was generated by a particular
 * assistant or model. All rows use the same documented editor events; optional
 * adapters only cover separately configured generation metadata workflows.
 */

const OBSERVATION = Object.freeze('workspace-document-events');
const ATTRIBUTION = Object.freeze('none');

const WORKSPACE_PROVIDER_MATRIX = Object.freeze([
  Object.freeze({
    id: 'github-copilot',
    label: 'GitHub Copilot',
    workflow: 'Assistant-produced code edited in the monitored workspace',
    workspaceMonitoring: 'supported',
    observation: OBSERVATION,
    attribution: ATTRIBUTION,
    optionalAdapters: Object.freeze(['vscode-language-model']),
    note: 'No private API is used; monitoring is identical for any text in a workspace document.'
  }),
  Object.freeze({
    id: 'cursor',
    label: 'Cursor',
    workflow: 'Cursor-generated code once edited in the monitored VS Code workspace',
    workspaceMonitoring: 'supported',
    observation: OBSERVATION,
    attribution: ATTRIBUTION,
    optionalAdapters: Object.freeze([]),
    note: 'No extension interception or reverse engineering; only ordinary document events.'
  }),
  Object.freeze({
    id: 'claude',
    label: 'Claude-assisted workflows',
    workflow: 'Claude-assisted code once written into a monitored document',
    workspaceMonitoring: 'supported',
    observation: OBSERVATION,
    attribution: ATTRIBUTION,
    optionalAdapters: Object.freeze(['openai-compatible', 'extension-api']),
    note: 'Optional adapters require explicit documented configuration and never alter scan results.'
  }),
  Object.freeze({
    id: 'chatgpt',
    label: 'ChatGPT-generated pasted code',
    workflow: 'Code pasted into a file',
    workspaceMonitoring: 'supported',
    observation: OBSERVATION,
    attribution: ATTRIBUTION,
    optionalAdapters: Object.freeze(['openai-compatible']),
    note: 'A paste is treated as a document change; its origin is not inferred.'
  }),
  Object.freeze({
    id: 'opencode',
    label: 'OpenCode',
    workflow: 'Code written by OpenCode into workspace files',
    workspaceMonitoring: 'supported',
    observation: OBSERVATION,
    attribution: ATTRIBUTION,
    optionalAdapters: Object.freeze(['openai-compatible', 'extension-api']),
    note: 'No provider-specific API is required for monitoring.'
  }),
  Object.freeze({
    id: 'other-assistants',
    label: 'Other VS Code AI coding assistants',
    workflow: 'Any assistant output saved as a source file in the workspace',
    workspaceMonitoring: 'supported',
    observation: OBSERVATION,
    attribution: ATTRIBUTION,
    optionalAdapters: Object.freeze(['extension-api']),
    note: 'Editor-level observation is the universal fallback for unknown tools.'
  }),
  Object.freeze({
    id: 'manual-code',
    label: 'Manually written code',
    workflow: 'Human-authored edits in a workspace document',
    workspaceMonitoring: 'supported',
    observation: OBSERVATION,
    attribution: ATTRIBUTION,
    optionalAdapters: Object.freeze([]),
    note: 'Human edits are intentionally indistinguishable from assistant edits.'
  })
]);

const WORKSPACE_EVENTS = Object.freeze([
  'onDidOpenTextDocument',
  'onDidChangeTextDocument',
  'onDidSaveTextDocument',
  'onDidCreateFiles',
  'onDidDeleteFiles',
  'onDidChangeWorkspaceFolders'
]);

/** @returns {Array<object>} */
function toWorkspaceProviderMatrix() {
  return WORKSPACE_PROVIDER_MATRIX.map((entry) => ({
    ...entry,
    optionalAdapters: [...entry.optionalAdapters]
  }));
}

/**
 * Render the matrix for documentation and the assistant-capability UI.
 *
 * @returns {string}
 */
function renderWorkspaceProviderMatrixMarkdown() {
  const rows = toWorkspaceProviderMatrix().map(
    (entry) =>
      `| ${entry.label} | ${entry.workspaceMonitoring} | ${entry.observation} | ` +
      `${entry.attribution} | ${entry.optionalAdapters.join(', ') || 'none'} | ${entry.note} |`
  );
  return [
    '# Workspace monitoring provider matrix',
    '',
    'Monitoring depends on code being present in the workspace, not on assistant identity.',
    '',
    '| Source or workflow | Workspace monitoring | Observation | Attribution | Optional adapters | Notes |',
    '|---|---|---|---|---|---|',
    ...rows,
    '',
    '## Official events',
    '',
    ...WORKSPACE_EVENTS.map((event) => `- \`${event}\``),
    '',
    'Attribution is always `none` unless reliable provider-supplied metadata is available.',
    'Private APIs and reverse-engineered extension internals are never used.'
  ].join('\n');
}

module.exports = {
  OBSERVATION,
  ATTRIBUTION,
  WORKSPACE_EVENTS,
  WORKSPACE_PROVIDER_MATRIX,
  toWorkspaceProviderMatrix,
  renderWorkspaceProviderMatrixMarkdown
};
